UPDATE articulos a SET contenido=(SELECT string_agg(coalesce(v.texto,substring(a.contenido from v.inicio for v.largo)),'' ORDER BY v.orden) FROM (VALUES (0, 1, 51, NULL::text),(1,0,0,E'<thead><tr><th scope="col">Condición de aceptación del sistema o componente mecánico</th><th scope="col">Cumple</th><th scope="col">No cumple</th><th scope="col">N/A*</th></tr></thead>'),(2, 52, 7, NULL::text),(3, 180, 29, NULL::text),(4,0,0,E'<td colspan="3">'),(5, 213, 45, NULL::text),(6,0,0,E'a) Los forros de balata adheridos deben tener un grosor igual o mayor a 1.6 mm (1/16") al medirse en cualquier punto excepto en la superficie biselada de la zapata.'),(7, 427, 45, NULL::text),(8,0,0,E'b) Los forros de balata remachados deben tener un grosor igual o mayor a 3.2 mm (1/8") al medirse en cualquier punto, excepto en la superficie biselada de la zapata; la superficie debe estar menos desgastada que las dimensiones especificadas por el fabricante y en ningún caso la medida debe ser menor a 8 mm. (1/32") a la cabeza del remache.'),(9, 824, 1489, NULL::text),(10,0,0,E'h) Las combinaciones de rectificado y desgaste en el diámetro interior del tambor deben ser iguales o menores que la medida estampada en el tambor; en caso de que la medida no se encuentre estampada en el tambor o, si el límite del fabricante no está disponible o, el límite de desgaste no está especificado por el fabricante del vehículo entonces la combinación de desgaste y rectificado no puede exceder 2.3 mm (0.090") por encima del diámetro original del tambor de 350 mm (14") o menos o 3.0 mm (0.120") por encima del diámetro original del tambor de más de 350 mm (14").'),(11, 2908, 202, NULL::text)) v(orden,inicio,largo,texto)) WHERE a.id='712fb0e6-b030-5b9c-a336-d122e31c924d' AND md5(a.contenido)='b4a3db5228f75b44f001e676cc1d7f78' RETURNING a.id,md5(a.contenido) hash;